from taf.ul.ettf.msg_capture.expectation_builders import Event, State


class FullMessage(Event):
    def __init__(self, matcher):
        self.matcher = self._prepare_matcher(matcher)
        super(FullMessage, self).__init__()


class FullMessageBuilder(State):
    def __init__(self, *args, **kwargs):
        self.matcher = None
        super(FullMessageBuilder, self).__init__(*args, **kwargs)

    def process(self, event):
        assert type(event) is FullMessage, 'Not available event {}'.format(type(event))
        assert self.matcher is None, 'Builder should finish before processing another event'
        self.matcher = event.matcher

    def finish(self):
        if self.matcher is not None:
            self.expectations.append(self.matcher(self.storage))
            self._clear()

    def _clear(self):
        self.matcher = None
